const body = $input.first().json;

if (!body.images || body.images.length !== 4) {
  throw new Error('images array must have exactly 4 paths');
}
if (!body.titles || body.titles.length !== 4) {
  throw new Error('titles array must have exactly 4 items');
}
if (!body.captions || body.captions.length !== 4) {
  throw new Error('captions array must have exactly 4 items');
}

return [{
  json: {
    ...body,
    output_dir: body.output_dir || '/output',
    tick_sound: body.tick_sound || '/templates/audio/tick.mp3',
    outro_sound: body.outro_sound || '/templates/audio/outro.mp3',
    font_path: body.font_path || '/templates/fonts/bold.ttf',
    platforms: body.platforms || ['tiktok_reels', 'youtube_shorts'],
    webhook_url: body.webhook_url || null,
    validated_at: new Date().toISOString()
  }
}];

const result = $input.first().json;
const status = result.status;
const outputs = result.outputs || {};

console.log('Render completed:', JSON.stringify(result, null, 2));

if (status === 'error') {
  throw new Error('All platforms failed: ' + JSON.stringify(result.errors));
}

return [{ json: { ...result, processed_at: new Date().toISOString() } }];
